#pragma once
#include "DeviceReader.h"
#include <newdev.h>
#pragma comment(lib,"newdev.lib")
namespace hub {
// Explicit command-line deployment only; never invoked by opening H hub or changing EQ.
inline int installEqDriver(std::filesystem::path inf,std::filesystem::path report){JsonObject result;HDEVINFO set=INVALID_HANDLE_VALUE;SP_DEVINFO_DATA device{sizeof(device)};bool registered=false;try{inf=std::filesystem::absolute(inf);if(inf.filename()!=L"vbMmeCable64_win10.inf"||!std::filesystem::is_regular_file(inf))throw hresult_invalid_argument(L"必须使用官方 Pack45 x64 INF");GUID cls{};wchar_t className[256]{};if(!SetupDiGetINFClassW(inf.c_str(),&cls,className,256,nullptr))throw hresult_error(HRESULT_FROM_WIN32(GetLastError()));auto existing=SetupDiGetClassDevsW(&cls,nullptr,nullptr,DIGCF_PRESENT);if(existing!=INVALID_HANDLE_VALUE){bool found=false;for(DWORD i=0;;i++){SP_DEVINFO_DATA entry{sizeof(entry)};if(!SetupDiEnumDeviceInfo(existing,i,&entry))break;if(DeviceReader::upper(DeviceReader::prop(existing,entry,SPDRP_HARDWAREID))==L"VBAUDIOVACWDM")found=true;}SetupDiDestroyDeviceInfoList(existing);if(found)throw hresult_error(E_ABORT,L"已有 VB-CABLE 设备，请使用官方安装程序修复");}set=SetupDiCreateDeviceInfoList(&cls,nullptr);if(set==INVALID_HANDLE_VALUE)throw hresult_error(HRESULT_FROM_WIN32(GetLastError()));if(!SetupDiCreateDeviceInfoW(set,L"VBAudioVACWDM",&cls,L"VB-Audio Virtual Cable",nullptr,DICD_GENERATE_ID,&device))throw hresult_error(HRESULT_FROM_WIN32(GetLastError()));wchar_t hardware[]=L"VBAudioVACWDM\0";if(!SetupDiSetDeviceRegistryPropertyW(set,&device,SPDRP_HARDWAREID,(BYTE*)hardware,sizeof(hardware))||!SetupDiCallClassInstaller(DIF_REGISTERDEVICE,set,&device))throw hresult_error(HRESULT_FROM_WIN32(GetLastError()));registered=true;BOOL reboot{};if(!UpdateDriverForPlugAndPlayDevicesW(nullptr,L"VBAudioVACWDM",inf.c_str(),0,&reboot))throw hresult_error(HRESULT_FROM_WIN32(GetLastError()));put(result,L"ok",true);put(result,L"rebootRequired",reboot!=FALSE);wchar_t instance[4096]{};SetupDiGetDeviceInstanceIdW(set,&device,instance,4096,nullptr);put(result,L"instance",std::wstring(instance));write(report,std::wstring(result.Stringify()));SetupDiDestroyDeviceInfoList(set);return 0;}catch(hresult_error const& e){put(result,L"ok",false);put(result,L"error",std::wstring(e.message()));put(result,L"hresult",(double)e.code().value);if(registered)SetupDiCallClassInstaller(DIF_REMOVE,set,&device);if(set!=INVALID_HANDLE_VALUE)SetupDiDestroyDeviceInfoList(set);write(report,std::wstring(result.Stringify()));return 1;}}
}
